    14|    g_in_safe_mode = false;
    15|}
    16|
    17|void fault_detector_heartbeat(bool imu_has_data) {
    18|    if (imu_has_data) {
    19|        g_timeout_count = 0;
    20|        g_in_safe_mode = false;
    21|        return;
    22|    }
    23|    // 连续无数据超过100ms? 由调用方每10ms调用，连续10次无数据
    24|    static uint8_t no_data_cnt = 0;
    25|    if (!imu_has_data) {
    26|        no_data_cnt++;
    27|        if (no_data_cnt >= 10) { // 100ms
    28|            no_data_cnt = 0;
    29|            // 触发告警
    30|            Event evt;
    31|            evt.type = EVT_SYNC;
    32|            evt.timestamp_ms = g_system_tick_ms;
    33|            evt.data.sync.sync_type = 1; // 告警
    34|            event_publish(&evt);
    35|            // 尝试切换采样率
    36|            // 降级：通知詹诗涵切换100Hz
    37|            g_timeout_count++;
    38|            if (g_timeout_count >= 3) {
    39|                // 进入安全模式
    40|                g_in_safe_mode = true;
    41|                power_manager_set_state(PM_SLEEP);
    42|                // 禁用体感音游（可通过EventBus）
    43|            }
    44|        }
    45|    } else {
    46|        no_data_cnt = 0;
    47|    }
