    45|// 内部函数：处理下一个请求（由定时器回调触发）
    46|void vibrate_process_next(void) {
    47|    if (g_vib_head == g_vib_tail) {
    48|        g_vib_busy = false;
    49|        return;
    50|    }
    51|    // 从队列中选出最高优先级（最小priority值）
    52|    int best_idx = -1;
    53|    VibPriority best_prio = VIB_PRIO_MAX;
    54|    for (int i = g_vib_head; i != g_vib_tail; i = (i+1)%QUEUE_DEPTH) {
    55|        if (g_vib_queue[i].priority < best_prio) {
    56|            best_prio = g_vib_queue[i].priority;
    57|            best_idx = i;
    58|        }
    59|    }
    60|    if (best_idx == -1) {
